/* @lc app=leetcode id=4037 lang=kotlin */ class Solution { fun g(a: Int, b: Int): Int = if (b == 0) a else g(b, a % b) fun rq(sp: List<IntArray>, l: Int, r: Int): Int = if (l > r) 0 else (31 - Integer.numberOfLeadingZeros(r - l + 1)).let { j -> g(sp[j][l], sp[j][r - (1 shl j) + 1]) } fun lt(lo: Int, hi: Int, p: (Int) -> Boolean): Int = generateSequence(lo to hi + 1) { (a, b) -> if (a < b) ((a + b) / 2).let { m -> if (p(m)) m + 1 to b else a to m } else null }.last().first - 1 fun ft(lo: Int, hi: Int, p: (Int) -> Boolean): Int = generateSequence(lo to hi + 1) { (a, b) -> if (a < b) ((a + b) / 2).let { m -> if (p(m)) a to m else m + 1 to b } else null }.last().first fun maxValidSplits(nums: IntArray): Int = nums.size.let { n -> (1..16).fold(listOf(nums)) { acc, j -> acc + IntArray(maxOf(0, n - (1 shl j) + 1)) { i -> g(acc[j - 1][i], acc[j - 1][i + (1 shl (j - 1))]) } }.let { sp -> nums.runningFold(0) { a, b -> g(a, b) }.drop(1).toIntArray().let { P -> nums.reversed().runningFold(0) { a, b -> g(a, b) }.reversed().toIntArray().let { S -> P.indices.reversed().associateBy { P[it] }.let { fP -> (0 until n).associateBy { S[it] }.let { lS -> maxOf(maxOf(0, (lS[P[n - 1]] ?: 0) - (fP[P[n - 1]] ?: 0)), (0 until n).maxOf { r -> (if (r == 0) 0 else P[r - 1]).let { pl -> S[r + 1].let { sr -> g(pl, sr).let { G -> (if (r >= 2 && pl == G) maxOf(0, lt(0, r - 2) { c -> g(rq(sp, c + 1, r - 1), sr) == G } - (fP[G] ?: 0) + 1) else 0) + (if (sr == G && r + 1 <= n - 2) maxOf(0, minOf(n - 2, (lS[G] ?: 0) - 1) - maxOf(r + 1, ft(r + 1, n - 2) { c -> g(pl, rq(sp, r + 1, c)) == G }) + 1) else 0) + (if (r >= 1 && r <= n - 2 && pl == sr) 1 else 0) } } } }) } } } } } } }